export function saveEditedFile(state,hostname,path,content,user="root") { const host=state.hosts[hostname]; if(!host)throw new Error(`Unknown virtual host: ${hostname}`); host.files[path]=content; event(state,"info",`${user} saved ${path} on ${hostname}.`); return {path,lines:content===""?0:content.split("\n").length,bytes:new TextEncoder().encode(content).length}; }

const h = (state,s) => state.hosts[s.host];
const serviceState = (host,name) => host.services[name] || "inactive (dead)";
const isActive = value => value?.startsWith("active");
const activeServiceForEngine=(state,hostname,service)=>state.hosts[hostname]?.online&&isActive(state.hosts[hostname]?.services[service]);
const canonicalService=name=>({nfs:"nfs-server",nfs_server:"nfs-server",mysql:"mariadb"}[name]||name);
const lines = (...xs) => xs.filter(x=>x!==undefined).join("\n");
const normalizeVirtualPath=path=>{const parts=[];for(const part of path.split("/")){if(!part||part===".")continue;if(part==="..")parts.pop();else parts.push(part);}return `/${parts.join("/")}`||"/";};
