function virtualFileBytes(path,content){if(basename(path).startsWith("core."))return 56*1024**3;const bytes=new TextEncoder().encode(content||"").length;return Math.max(4096,Math.ceil(bytes/4096)*4096);}
function virtualUsageBytes(host,path){if(host.files[path]!==undefined&&!isVirtualDirectory(host,path))return virtualFileBytes(path,host.files[path]);const prefix=path==="/"?"/":`${path}/`;return Object.entries(host.files).filter(([file])=>file.startsWith(prefix)).reduce((sum,[file,content])=>sum+virtualFileBytes(file,content),0);}
