const logPathFor=(hostname,service)=>({haproxy:"/var/log/haproxy.log",mariadb:"/var/log/mariadb/mariadb.log",mysql:"/var/log/mariadb/mariadb.log",drbd:"/var/log/drbd.log",pacemaker:"/var/log/pacemaker/pacemaker.log",corosync:"/var/log/cluster/corosync.log","nfs-server":"/var/log/nfs.log",nfs_server:"/var/log/nfs.log","pure-ftpd":"/var/log/pureftpd.log",NetworkManager:"/var/log/messages","rabbitmq-server":`/var/log/rabbitmq/rabbit@${hostname}.log`,cassandra:"/var/log/cassandra/system.log",elasticsearch:"/var/log/elasticsearch/lab-search.log",libvirtd:"/var/log/libvirt/libvirtd.log"}[service]||"/var/log/messages");
function appendLog(state,hostname,path,message){const host=state.hosts[hostname];if(!host)return;host.files[path]=(host.files[path]||"")+message.replace(/\n?$/,"\n");}
function serviceLog(state,hostname,service,message,level="error"){const upper=level.toUpperCase();appendLog(state,hostname,"/var/log/messages",`Aug 02 09:18:42 ${hostname} ${service}[${service==="pacemaker"?1402:3210}]: ${upper}: ${message}`);const path=logPathFor(hostname,service);if(path!=="/var/log/messages")appendLog(state,hostname,path,`Aug 02 09:18:42 ${hostname} ${service}[3210]: ${upper}: ${message}`);}

function shellWords(raw) {
  const out=[]; let cur="", quote="";
  for(let i=0;i<raw.length;i++){ const c=raw[i]; if(quote){ if(c===quote) quote=""; else cur+=c; } else if(c==="'"||c==='"') quote=c; else if(/\s/.test(c)){ if(cur){out.push(cur);cur="";} } else cur+=c; }
  if(cur) out.push(cur); return out;
}

function clusterForHost(state,hostname){ return Object.entries(state.clusters).find(([,c])=>c.nodes.includes(hostname)); }
function failover(state,clusterName,failed){
  const c=state.clusters[clusterName]; if(!c||c.owner!==failed) return;
  const target=c.nodes.find(n=>n!==failed&&state.hosts[n].online);
  if(!target){ c.owner=null; c.quorum=false; c.nodes.forEach(n=>serviceLog(state,n,"pacemaker",`${clusterName} resource group stopped: no eligible VIP owner`,"critical"));event(state,"critical",`${clusterName} has no eligible VIP owner.`); return; }
  c.owner=target; c.quorum=true;if(c.dc===failed||!state.hosts[c.dc]?.online)c.dc=target;
  if(clusterName==="database"){ state.mysql.primary=target; c.roles="Secondary/Primary"; const svc=state.hosts[target].services; svc.mariadb="active (running)"; }
  if(clusterName==="storage"){c.roles="Secondary/Primary";state.hosts[target].services["nfs-server"]="active (running)";}
  serviceLog(state,failed,"pacemaker",`monitor operation failed for ${clusterName}; initiating recovery`,"warning");
  serviceLog(state,target,"pacemaker",`Started vip-${clusterName} ${c.vip} after migration from ${failed}`,"notice");
  event(state,"warning",`${c.vip} migrated from ${failed} to ${target}.`);
}

export function setHostPower(state,hostname,action,source="terminal"){
  const host=state.hosts[hostname];if(!host)return `Error: virtual machine '${hostname}' not found`;
  const entry=clusterForHost(state,hostname);
  const startHost=()=>{host.online=true;host.uptime="0 min";if(host.powerServices){host.services={...host.services,...host.powerServices};delete host.powerServices;}else Object.keys(host.services).forEach(service=>host.services[service]="active (running)");if(entry){const [name,cluster]=entry;cluster.quorum=cluster.nodes.some(node=>state.hosts[node].online);cluster.dc??=cluster.nodes.find(node=>state.hosts[node].online);["pacemaker","corosync","drbd"].forEach(service=>{if(service in host.services)host.services[service]="active (running)";});if(name==="database")host.services.mariadb=cluster.owner===hostname?"active (running)":"inactive (dead)";if(name==="storage")host.services["nfs-server"]=cluster.owner===hostname?"active (running)":"inactive (dead)";}serviceLog(state,hostname,"systemd","virtual machine boot completed; services restored","notice");};
  if(action==="start"){if(host.online)return `Domain ${hostname} is already running`;startHost();if(source==="management")host.history.push(`powerctl start ${hostname}`);event(state,"info",`${hostname} ${source==="management"?"node powered on through out-of-band management":"virtual machine started"}.`);return `Domain ${hostname} started`;}
  if(action!=="shutdown"&&action!=="reboot")return `Error: unsupported power action '${action}'`;
  if(!host.online)return `Domain ${hostname} is not running`;
  host.powerServices={...host.services};host.online=false;host.uptime="0 min";Object.keys(host.services).forEach(service=>host.services[service]="inactive (dead)");if(entry){failover(state,entry[0],hostname);if(entry[1].dc===hostname)entry[1].dc=entry[1].nodes.find(node=>state.hosts[node].online)||null;}
  if(action==="shutdown"){event(state,"warning",`${hostname} virtual machine shut down.`);return `Domain ${hostname} is being shutdown`;}
  startHost();event(state,"info",`${hostname} virtual machine reboot completed.`);return `Domain ${hostname} rebooted`;
}

