  if(cmd==="rmdir"){const errors=[];for(const target of args.filter(a=>!a.startsWith("-"))){const p=resolvePath(s,target);if(!isVirtualDirectory(host,p)){errors.push(`rmdir: failed to remove '${target}': No such file or directory`);continue;}const hasChildren=virtualPaths(host).some(path=>path!==p&&parentPath(path)===p);if(hasChildren){errors.push(`rmdir: failed to remove '${target}': Directory not empty`);continue;}host.directories=host.directories.filter(path=>path!==p);}return errors.join("\n");}
  if(cmd==="cp"||cmd==="mv"){const cleanArgs=args.filter(a=>!a.startsWith("-")),sourceArg=cleanArgs.at(-2),destArg=cleanArgs.at(-1),src=resolvePath(s,sourceArg),destination=resolvePath(s,destArg),dst=isVirtualDirectory(host,destination)?`${destination.replace(/\/$/,"")}/${basename(src)}`:destination;if(!virtualPathExists(host,src))return `${cmd}: cannot stat '${sourceArg}': No such file or directory`;if(isVirtualDirectory(host,src))return `${cmd}: -r not specified; omitting directory '${sourceArg}'`;if(!isVirtualDirectory(host,parentPath(dst)))return `${cmd}: cannot create regular file '${destArg}': No such file or directory`;host.files[dst]=host.files[src];if(cmd==="mv")delete host.files[src];return ""; }
