    for(const rawTarget of rawTargets){const expanded=expandVirtualTarget(host,s,rawTarget),targets=expanded.length?expanded:[rawTarget];for(const target of targets){const p=resolvePath(s,target),directory=isVirtualDirectory(host,p);if(directory&&!recursive){errors.push(`rm: cannot remove '${target}': Is a directory`);continue;}if(directory){const prefix=p==="/"?"/":`${p}/`;for(const file of Object.keys(host.files).filter(file=>file.startsWith(prefix))){removedCore||=basename(file).startsWith("core.");delete host.files[file];removed++;}continue;}if(host.files[p]!==undefined){removedCore||=basename(p).startsWith("core.");delete host.files[p];removed++;}else if(!force)errors.push(`rm: cannot remove '${target}': No such file or directory`);}}
